def _sid2_live_store_inventory() -> tuple[int, str, tuple[str, ...]]:
    """Independently hash the exact live SID2 tree without following links."""
    store = REPOSITORY / "runs/fgc-2-sf1/proto17/calibration"
    stack = [store]
    rows: list[tuple[str, int, str]] = []
    directories: list[str] = []
    while stack:
        directory = stack.pop()
        with os.scandir(directory) as entries:
            ordered = sorted(entries, key=lambda entry: entry.name)
        for entry in ordered:
            metadata = entry.stat(follow_symlinks=False)
            relative = Path(entry.path).relative_to(store).as_posix()
            if stat.S_ISLNK(metadata.st_mode):
                raise ValueError("SID2 live tree contains a symlink")
            if stat.S_ISDIR(metadata.st_mode):
                directories.append(relative)
                stack.append(Path(entry.path))
                continue
            if not stat.S_ISREG(metadata.st_mode) or metadata.st_nlink != 1:
                raise ValueError("SID2 live tree contains a nonunique special leaf")
            descriptor = os.open(
                entry.path,
                os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0),
            )
            try:
                observed = os.fstat(descriptor)
                if (
                    observed.st_dev != metadata.st_dev
                    or observed.st_ino != metadata.st_ino
                    or observed.st_size != metadata.st_size
                    or observed.st_nlink != 1
                    or not stat.S_ISREG(observed.st_mode)
                ):
                    raise ValueError("SID2 live tree changed during audit")
                digest = sha256()
                while block := os.read(descriptor, 1024 * 1024):
                    digest.update(block)
            finally:
                os.close(descriptor)
            rows.append((relative, metadata.st_size, digest.hexdigest()))
    encoded = b"".join(
        path.encode("utf-8")
        + b"\0"
        + str(size).encode("ascii")
        + b"\0"
        + digest.encode("ascii")
        + b"\n"
        for path, size, digest in sorted(rows)
    )
    return len(rows), sha256(encoded).hexdigest(), tuple(sorted(directories))


def _check_pro19_sid2_postrecovery_result() -> list[str]:
    """Own SID2's one-time exact generation-eight live-store verification."""
    failures = _check_pro19_prelaunch_result() + _check_pro19_sid2_compact_result()
    if failures:
        return failures
    try:
        count, inventory, directories = _sid2_live_store_inventory()
    except (OSError, ValueError) as exc:
        return [f"FGC-1-PRO19-SID2-PREF1 live store is unsafe: {exc}"]
    if (
        count != 52
        or inventory
        != "8196b088a19f70ae1016a3d9dddb508add1ce1ce5cd227d105c954bd0c151c27"
        or directories
        != ("checkpoints", "journal", "locks", "payloads", "receipts", "states")
    ):
        return ["FGC-1-PRO19-SID2-PREF1 live store inventory differs"]
    check = subprocess.run(
        [sys.executable, "scripts/reproduce_fgc_pro19_sid2_pref1.py", "--verify"],
        cwd=REPOSITORY,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        check=False,
    )
    return (
        []
        if check.returncode == 0
        else ["FGC-1-PRO19-SID2-PREF1 exact post-recovery reproduction failed"]
    )


_PRO19_SID3_BUNDLE = (
    "configs/fgc/fgc-1-pro19-sid3-auth1.toml",
    "configs/fgc/fgc-1-pro19-sid3-execution-closure.json",
    "results/fgc-1-pro19-sid3-auth1.json",
    "docs/fgc-pro19-sid3-auth1.md",
)


def _check_pro19_sid3_compact_result(*, required: bool = False) -> list[str]:
    """Verify SID3 compact evidence without opening the mutable run store.

    SID3's four non-Python authority artifacts are intentionally absent from
    the implementation commit that first introduces this route.  Therefore a
    completely absent bundle is accepted by ordinary repository verification,
    while a partial bundle is always rejected.  Once the bundle exists, the
    compact reproducer owns exact config/closure/result validation; neither
    this route nor that reproducer is permitted to inspect generation eight.
    """

    present: list[str] = []
    missing: list[str] = []
    for relative in _PRO19_SID3_BUNDLE:
        path = REPOSITORY / relative
        try:
            metadata = path.lstat()
        except FileNotFoundError:
            missing.append(relative)
            continue
        except OSError as exc:
            return [f"cannot inspect FGC-1-PRO19-SID3-AUTH1 bundle: {exc}"]
        if not stat.S_ISREG(metadata.st_mode) or metadata.st_nlink != 1:
            return [f"FGC-1-PRO19-SID3-AUTH1 bundle path is unsafe: {relative}"]
        present.append(relative)

    if not present:
        return (
            ["FGC-1-PRO19-SID3-AUTH1 compact bundle is absent"]
            if required
            else []
        )
    if missing:
        return [
            "FGC-1-PRO19-SID3-AUTH1 compact bundle is partial; missing: "
            + ", ".join(missing)
        ]

    check = subprocess.run(
        [
            sys.executable,
            "scripts/reproduce_fgc_pro19_sid3_auth1.py",
            "--verify",
        ],
        cwd=REPOSITORY,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        check=False,
    )
    if check.returncode:
        detail = check.stderr.strip() or check.stdout.strip()
        return [
            "FGC-1-PRO19-SID3-AUTH1 compact reproduction failed"
            + (f": {detail}" if detail else "")
        ]
    return []


